<?php
declare(strict_types=1);session_start();require dirname(__DIR__).'/config/config.php';require_sign_in();
$role=(string)$_SESSION['role'];if(!in_array($role,['admin','director','sub_director','headteacher','head_academic'],true)){http_response_code(403);exit('Your role cannot manage announcements.');}$uid=(int)$_SESSION['user_id'];$db=db();$q=$db->prepare('SELECT s.id,s.name FROM schools s JOIN school_memberships m ON m.school_id=s.id WHERE m.user_id=? ORDER BY s.name');$q->execute([$uid]);$schools=$q->fetchAll();$ids=array_map('intval',array_column($schools,'id'));if(!$ids){http_response_code(403);exit('No school is linked to your account.');}$school=(int)($_GET['school_id']??$ids[0]);if(!in_array($school,$ids,true)){http_response_code(403);exit('That school is outside your access.');}$schoolName='School';foreach($schools as $x)if((int)$x['id']===$school)$schoolName=$x['name'];$q=$db->prepare('SELECT * FROM school_announcements WHERE school_id=? ORDER BY created_at DESC LIMIT 200');$q->execute([$school]);$announcements=$q->fetchAll();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Announcements · ShuleLite</title><link rel="stylesheet" href="assets/app.css"><script defer src="assets/app.js"></script><script defer src="assets/api.js"></script><script defer src="assets/announcements.js"></script></head><body><div class="app-shell"><?php require __DIR__.'/sidebar.php';?><main class="main-area"><header class="topbar"><button class="icon-button menu-toggle" data-menu aria-label="Open navigation" aria-expanded="false">☰</button><div class="crumb">Workspace <span>/</span> Announcements</div><div class="top-actions"><span class="role-chip"><?=e(str_replace('_',' ',$role))?></span><div class="user-name"><?=e((string)($_SESSION['name']??'User'))?></div></div></header><div class="page-content"><section class="welcome-row"><div><div class="eyebrow">SCHOOL COMMUNICATION</div><h1>Announcements</h1><p class="muted"><?=e($schoolName)?> · Publish notices to staff, parents, pupils, or everyone.</p></div><?php if(count($schools)>1):?><form method="get"><label for="announcement-school">School</label><select id="announcement-school" name="school_id" onchange="this.form.submit()"><?php foreach($schools as $x):?><option value="<?=$x['id']?>"<?=(int)$x['id']===$school?' selected':''?>><?=e($x['name'])?></option><?php endforeach;?></select></form><?php endif;?></section><section class="note-create"><div class="section-heading"><div><div class="eyebrow">NEW NOTICE</div><h2>Draft an announcement</h2></div></div><form method="post" data-announcement-form><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="school_id" value="<?=$school?>"><input type="hidden" name="action" value="create"><div class="form-grid"><div><label for="announcement-title">Title</label><input id="announcement-title" name="title" maxlength="180" required></div><div><label for="announcement-audience">Audience</label><select id="announcement-audience" name="audience"><option value="all">All school community</option><option value="parents">Parents and guardians</option><option value="pupils">Pupils</option><option value="staff">Staff</option></select></div><div><label for="announcement-expires">Optional expiry</label><input id="announcement-expires" type="date" name="expires_at"></div><div class="form-span"><label for="announcement-body">Announcement</label><textarea id="announcement-body" name="body" maxlength="30000" rows="6" required></textarea></div></div><button class="button primary" type="submit">Save draft</button></form></section><section class="content-section"><div class="section-heading"><div><div class="eyebrow">NOTICE BOARD</div><h2>Announcements</h2></div><span class="count-pill"><?=count($announcements)?> notices</span></div><?php if($announcements):?><div class="question-list"><?php foreach($announcements as $a):?><article class="question-card"><div class="section-heading"><div><h3><?=e($a['title'])?></h3><p class="muted"><?=e(ucfirst($a['audience']))?> · <?=e(ucfirst($a['status']))?><?php if($a['expires_at']):?> · Expires <?=e(date('j M Y',strtotime($a['expires_at'])))?><?php endif;?></p></div></div><div><?=nl2br(e($a['body']))?></div><p class="muted">Created <?=e(date('j M Y H:i',strtotime($a['created_at'])))?></p><?php if($a['status']==='draft'):?><form method="post" class="ops-actions" data-announcement-form><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="school_id" value="<?=$school?>"><input type="hidden" name="announcement_id" value="<?=$a['id']?>"><button class="button primary" name="action" value="publish">Publish</button><button class="button danger" name="action" value="archive">Archive draft</button></form><?php elseif($a['status']==='published'):?><form method="post" data-announcement-form><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="school_id" value="<?=$school?>"><input type="hidden" name="announcement_id" value="<?=$a['id']?>"><button class="button danger" name="action" value="archive">Archive notice</button></form><?php endif;?></article><?php endforeach;?></div><?php else:?><div class="empty-state"><h3>No announcements yet</h3><p>Draft a school notice and publish it to the appropriate audience.</p></div><?php endif;?></section><footer class="page-footer">ShuleLite <span>·</span> School communication</footer></div></main></div></body></html>
